import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times.  Return the result of the first
    successful call.  If all attempts fail, re‑raise the last exception
    without performing a final sleep.
    """
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception as exc:
            # If this was the last attempt, re‑raise the exception.
            if attempt == max_attempts - 1:
                raise
            # Otherwise wait a bit before retrying.
            time.sleep(0.01 * (attempt + 1))
