def is_balanced(s):
    """
    Return True if the string s contains correctly nested and matched
    parentheses, square brackets, and curly braces.
    """
    # Mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())

    stack = []

    for c in s:
        if c in opening:
            stack.append(c)
        elif c in pairs:
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()
        else:
            # Ignore any other characters
            continue

    return not stack
